static size_t fill_units(size_t padding, size_t fill_size) {
  if (padding == 0) return 0;
  if (fill_size == 0) return 0;
  if (fill_size == 1) return padding;
  if (padding > max_value<size_t>() / fill_size) return padding * fill_size;
  return padding * fill_size;
}

static int errno_kind(int err) {
  if (err == 0) return 0;
  if (err == EINTR) return 1;
  #ifdef EAGAIN
  if (err == EAGAIN) return 2;
